    def config(
        self,
        protocol: str,
        *,
        asset: str | None = None,
    ) -> LendingMarketConfigResponse:
        """The risk configuration of a lending protocol's markets.

        The configuration of every asset of a lending protocol's markets (or of one,
        with `asset`), as its last configuration events set it (or its initialization
        did): loan-to-value, liquidation threshold, reserve factor and liquidation
        protocol fee (basis points), the liquidation bonus (basis points over the debt
        repaid: 500 = 5 %), supply and borrow caps (whole tokens; absent = no cap),
        whether the asset is active, frozen or paused, its price oracle, and the
        contracts of its receipt and debt tokens and its rate strategy. `coveredMarkets`
        names the markets TraceFast reads (Aave V3's main Ethereum market today);
        `protocol` must be one of them. A value is absent when the asset's
        initialization is not in the history TraceFast reads.

        Plan: Intelligence or higher.

        Args:
            protocol: A covered protocol, for example `aave_v3`; another value is
                refused (`protocol_invalid`) with the covered list.
            asset: Only this asset (`0x` + 40 hex).

        Returns:
            `LendingMarketConfigResponse`: the whole answer, `data` and `meta`.

        Raises:
            TraceFastError: The API refused the call or it failed; the subclass and
                `code` say why.
            ValueError: A path value is empty, `.` or `..`; nothing is sent.

        Docs: https://docs.tracefast.xyz/api/lending-config
        """
        return cast("LendingMarketConfigResponse", self._http.get(f"/chains/{self._http.chain_id}/lending/{segment(protocol)}/config", {"asset": asset}))


