    async def blobs_daily(
        self,
        *,
        from_: str | None = None,
        to: str | None = None,
    ) -> BlobsDailyResponse:
        """Blobs per day.

        Per UTC day, the EIP-4844 blobs posted, the transactions that carried them and
        how many distinct addresses sent those transactions. Days before blobs existed
        have no row. UTC dates `YYYY-MM-DD`: the window is `from` to `to`, both
        included, at most 366 days; by default the 30 days up to today. A day the source
        is still counting is `provisional`: today, and yesterday until the source's
        first run after midnight. A day the source has no row for is absent.

        Plan: Enriched Data or higher.

        Args:
            from_: The first UTC date, `YYYY-MM-DD`. Sent as `from`.
            to: The last UTC date, `YYYY-MM-DD`. Default: today.

        Returns:
            `BlobsDailyResponse`: the whole answer, `data` and `meta`.

        Raises:
            TraceFastError: The API refused the call or it failed; the subclass and
                `code` say why.

        Docs: https://docs.tracefast.xyz/api/network-blobs
        """
        return cast("BlobsDailyResponse", await self._http.get(f"/chains/{self._http.chain_id}/network/blobs", {"from": from_, "to": to}))

